    participants: { userId: row.ownerPrincipalId, userIds: row.participants, ...(row.legacyAgentLabel ? { agentId: row.legacyAgentLabel } : {}) },
    messages: [] as import("./_cortex/shared/types/index").Message[], messageCount: row.messageCount,
