export const addMessage = mutation({ args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    conversationId: v.string(),
    message: v.object({
      id: v.string(),
      role: v.union(v.literal("user"), v.literal("agent"), v.literal("system")),
