        const sortField = args.sortBy as
          | "createdAt"
          | "updatedAt"
          | "confidence"
          | "version";
        facts.sort((a, b) => {
          const aVal = a[sortField] as any;
          const bVal = b[sortField] as any;
          const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
          return args.sortOrder === "asc" ? comparison : -comparison;
